/**
 * File System Access API wrapper with fallback support
 *
 * Provides progressive enhancement for file operations:
 * - Chrome/Edge/Safari: Native File System Access API for save-in-place
 * - Firefox/older browsers: Traditional input element and download fallback
 *
 * Reference: https://developer.chrome.com/docs/capabilities/web-apis/file-system-access
 */

// TypeScript declarations for File System Access API
declare global {
  interface Window {
    showOpenFilePicker?: (options?: {
      types?: Array<{
        description?: string;
        accept: Record<string, string[]>;
      }>;
      multiple?: boolean;
    }) => Promise<FileSystemFileHandle[]>;
    showSaveFilePicker?: (options?: {
      suggestedName?: string;
      types?: Array<{
        description?: string;
        accept: Record<string, string[]>;
      }>;
    }) => Promise<FileSystemFileHandle>;
  }

  interface FileSystemFileHandle {
    getFile(): Promise<File>;
    createWritable(): Promise<FileSystemWritableFileStream>;
  }

  interface FileSystemWritableFileStream extends WritableStream {
    write(data: string | BufferSource | Blob): Promise<void>;
    close(): Promise<void>;
  }
}

/**
 * Result from opening a file
 */
export interface OpenFileResult {
  content: string;
  name: string;
  handle: FileSystemFileHandle | null;
}

/**
 * Check if File System Access API is available in this browser.
 */
export function hasFileSystemAccess(): boolean {
  return 'showOpenFilePicker' in window;
}

/**
 * Open a file using File System Access API with fallback.
 *
 * Returns file content, name, and handle (if API supported).
 * Handle can be used for save-in-place without showing save dialog.
 *
 * @returns Promise resolving to file content and handle, or null if cancelled
 */
export async function openFile(): Promise<OpenFileResult | null> {
  if (hasFileSystemAccess()) {
    // Modern API - Chrome, Edge, Safari
    try {
      const [handle] = await window.showOpenFilePicker!({
        types: [
          {
            description: 'PCB Design Files',
            accept: {
              'application/x-cypcb': ['.cypcb'],
              'application/x-specctra-ses': ['.ses'],
            },
          },
        ],
        multiple: false,
      });

      const file = await handle.getFile();
      const content = await file.text();

      return {
        content,
        name: file.name,
        handle,
      };
    } catch (err) {
      // User cancelled or permission denied
      if ((err as Error).name === 'AbortError') {
        console.log('[FileAccess] User cancelled file open');
        return null;
      }
      console.error('[FileAccess] Error opening file:', err);
      throw err;
    }
  } else {
    // Fallback - Firefox, older browsers
    return new Promise((resolve) => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = '.cypcb,.ses';

      input.onchange = async () => {
        const file = input.files?.[0];
        if (!file) {
          resolve(null);
          return;
        }

        try {
          const content = await file.text();
          resolve({
            content,
            name: file.name,
            handle: null, // No handle in fallback mode
          });
        } catch (err) {
          console.error('[FileAccess] Error reading file:', err);
          resolve(null);
        }

        // Clean up
        input.remove();
      };

      input.oncancel = () => {
        console.log('[FileAccess] User cancelled file open');
        input.remove();
        resolve(null);
      };

      input.click();
    });
  }
}

/**
 * Save a file using File System Access API with fallback.
 *
 * If handle is provided and valid, saves directly without showing dialog.
 * If no handle, shows save picker (if API available) or triggers download.
 *
 * @param content - File content to save
 * @param handle - File handle from previous open (if available)
 * @param defaultName - Default filename for save-as or download
 * @returns Promise resolving to file handle (for next save), or null if cancelled/fallback
 */
export async function saveFile(
  content: string,
  handle: FileSystemFileHandle | null,
  defaultName: string
): Promise<FileSystemFileHandle | null> {
  if (handle) {
    // Save to existing handle - no dialog
    try {
      const writable = await handle.createWritable();
      await writable.write(content);
      await writable.close();
      console.log('[FileAccess] File saved successfully');
      return handle; // Return same handle for next save
    } catch (err) {
      console.error('[FileAccess] Error saving file:', err);
      // If handle save fails, fall through to save-as
      handle = null;
    }
  }

  // No handle - need to get one
  if (hasFileSystemAccess() && !handle) {
    // Show save picker
    try {
      const newHandle = await window.showSaveFilePicker!({
        suggestedName: defaultName,
        types: [
          {
            description: 'PCB Design Files',
            accept: {
              'application/x-cypcb': ['.cypcb'],
            },
          },
        ],
      });

      const writable = await newHandle.createWritable();
      await writable.write(content);
      await writable.close();
      console.log('[FileAccess] File saved as:', defaultName);

      return newHandle; // Return new handle for future saves
    } catch (err) {
      // User cancelled or permission denied
      if ((err as Error).name === 'AbortError') {
        console.log('[FileAccess] User cancelled save');
        return null;
      }
      console.error('[FileAccess] Error saving file:', err);
      throw err;
    }
  } else {
    // Fallback - trigger download
    const blob = new Blob([content], { type: 'application/x-cypcb' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = defaultName;
    a.click();

    // Clean up
    setTimeout(() => {
      URL.revokeObjectURL(url);
      a.remove();
    }, 100);

    console.log('[FileAccess] File downloaded:', defaultName);
    return null; // No handle in fallback mode
  }
}

/**
 * File Picker Utilities
 *
 * Provides client-side file selection and reading for .cypcb and .ses files.
 * Uses standard browser File API, FileReader, and HTML Drag and Drop API.
 */

/**
 * Read a file as text using FileReader wrapped in a Promise.
 *
 * @param file - The File object to read
 * @returns Promise resolving to the file contents as a string
 */
export function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(reader.error);
    reader.readAsText(file);
  });
}

/**
 * Create a hidden file input element that can be triggered programmatically.
 *
 * @param accept - File type filter (e.g., ".cypcb,.ses")
 * @param onFile - Callback invoked when a file is selected
 * @returns The hidden input element (call .click() to open dialog)
 */
export function createFilePicker(
  accept: string,
  onFile: (file: File) => void
): HTMLInputElement {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = accept;
  input.style.display = 'none';

  input.addEventListener('change', () => {
    const file = input.files?.[0];
    if (file) {
      onFile(file);
    }
    // Reset to allow re-selecting the same file
    input.value = '';
  });

  document.body.appendChild(input);
  return input;
}

/**
 * Set up drag-and-drop on an element with visual feedback.
 *
 * Adds 'drag-over' CSS class when files are dragged over the element.
 * Also prevents window-level drop events from causing browser navigation.
 *
 * @param element - The drop zone element
 * @param onDrop - Callback invoked when a file is dropped
 */
export function setupDropZone(
  element: HTMLElement,
  onDrop: (file: File) => void
): void {
  // Counter handles child element drag events correctly
  let dragCounter = 0;

  element.addEventListener('dragenter', (e: DragEvent) => {
    e.preventDefault();
    dragCounter++;
    element.classList.add('drag-over');
  });

  element.addEventListener('dragleave', () => {
    dragCounter--;
    if (dragCounter === 0) {
      element.classList.remove('drag-over');
    }
  });

  element.addEventListener('dragover', (e: DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer) {
      e.dataTransfer.dropEffect = 'copy';
    }
  });

  element.addEventListener('drop', (e: DragEvent) => {
    e.preventDefault();
    dragCounter = 0;
    element.classList.remove('drag-over');

    const file = e.dataTransfer?.files[0];
    if (file) {
      onDrop(file);
    }
  });

  // Prevent browser from navigating when files are dropped outside the drop zone
  window.addEventListener('dragover', (e) => e.preventDefault());
  window.addEventListener('drop', (e) => e.preventDefault());
}

/**
 * Application settings persistence and change notification.
 *
 * Follows the same subscribe-notify pattern as ThemeManager but generalizes
 * to all user preferences. Stores a single JSON blob in localStorage under
 * the key 'cypcb-settings'. Missing or corrupt data falls back to defaults.
 *
 * Debug surface: `window.__settings` exposes the current snapshot for E2E.
 */

import type { DisplayUnit } from './units';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface LayerColors {
  topCopper: string;
  bottomCopper: string;
  silkscreen: string;
  via: string;
  drill: string;
}

export interface AppSettings {
  /** Theme preference: light, dark, or auto (follow OS) */
  theme: 'light' | 'dark' | 'auto';
  /** Display unit for dimensions */
  units: DisplayUnit;
  /** Visual grid spacing in nanometers */
  gridVisualSpacing: number;
  /** Snap grid spacing in nanometers */
  gridSnapSpacing: number;
  /** Whether the grid overlay is visible */
  gridVisible: boolean;
  /** Whether the ratsnest overlay is visible */
  ratsnestVisible: boolean;
  /** Whether net labels are visible */
  netLabelsVisible: boolean;
  /** Layer color overrides */
  layerColors: LayerColors;
}

export type SettingsKey = keyof AppSettings;
export type SettingsListener = (settings: AppSettings) => void;

// ---------------------------------------------------------------------------
// Defaults
// ---------------------------------------------------------------------------

/**
 * Default settings matching current hardcoded behavior:
 * - mm units
 * - 1mm visual grid (1_000_000 nm)
 * - 50mil snap grid (1_270_000 nm)
 * - all overlays visible
 * - standard RenderConfig layer colors
 */
export const DEFAULT_SETTINGS: Readonly<AppSettings> = {
  theme: 'auto',
  units: 'mm',
  gridVisualSpacing: 1_000_000,
  gridSnapSpacing: 1_270_000,
  gridVisible: true,
  ratsnestVisible: true,
  netLabelsVisible: true,
  layerColors: {
    topCopper: '#C83434',
    bottomCopper: '#3434C8',
    silkscreen: '#C8C800',
    via: '#808080',
    drill: '#FFFFFF',
  },
};

// ---------------------------------------------------------------------------
// Storage key
// ---------------------------------------------------------------------------

const STORAGE_KEY = 'cypcb-settings';

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

function loadFromStorage(): AppSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };

    const parsed = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) {
      console.warn('[settings] Invalid localStorage data, falling back to defaults');
      return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
    }

    // Merge parsed values over defaults so missing keys get filled in
    return {
      ...DEFAULT_SETTINGS,
      ...parsed,
      layerColors: {
        ...DEFAULT_SETTINGS.layerColors,
        ...(parsed.layerColors ?? {}),
      },
    };
  } catch (e) {
    console.warn('[settings] Failed to parse localStorage data, falling back to defaults', e);
    return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
  }
}

function saveToStorage(settings: AppSettings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    // Storage full or unavailable — silently degrade
  }
}

// ---------------------------------------------------------------------------
// Exported API
// ---------------------------------------------------------------------------

let current: AppSettings = loadFromStorage();
const listeners: Set<SettingsListener> = new Set();

function notifyListeners(): void {
  const snapshot = getSettings();
  listeners.forEach((fn) => fn(snapshot));
}

function exposeDebugSurface(): void {
  if (typeof window !== 'undefined') {
    (window as any).__settings = getSettings();
  }
}

/**
 * Get the full current settings snapshot (deep copy).
 */
export function getSettings(): AppSettings {
  return {
    ...current,
    layerColors: { ...current.layerColors },
  };
}

/**
 * Get a single preference value.
 */
export function getPreference<K extends SettingsKey>(key: K): AppSettings[K] {
  const val = current[key];
  // Deep-copy layerColors to prevent external mutation
  if (key === 'layerColors' && typeof val === 'object') {
    return { ...(val as any) } as AppSettings[K];
  }
  return val;
}

/**
 * Set a single preference value, persist to localStorage, and notify listeners.
 */
export function setPreference<K extends SettingsKey>(key: K, value: AppSettings[K]): void {
  // Deep-copy layerColors on write
  if (key === 'layerColors' && typeof value === 'object') {
    current[key] = { ...(value as any) } as AppSettings[K];
  } else {
    current[key] = value;
  }
  saveToStorage(current);
  exposeDebugSurface();
  notifyListeners();
}

/**
 * Subscribe to any settings change.
 * @returns Unsubscribe function.
 */
export function subscribe(listener: SettingsListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Reset all settings to defaults (useful for testing).
 */
export function resetSettings(): void {
  current = { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
  saveToStorage(current);
  exposeDebugSurface();
  notifyListeners();
}

// ---------------------------------------------------------------------------
// Initialize debug surface
// ---------------------------------------------------------------------------

exposeDebugSurface();

